        auto availableHeight = ImGui::GetContentRegionAvail().y;
        auto headerHeight = processHeaderData();
        if (!_layoutData->headerFittedToContent) {
            auto structureHeightBelowFittedHeader = availableHeight - headerHeight;
            if (structureHeightBelowFittedHeader >= headerHeight) {
                _layoutData->structureHeight = structureHeightBelowFittedHeader;
            }
            _layoutData->headerFittedToContent = true;
        }

        AlienGui::MovableHorizontalSeparator(AlienGui::MovableHorizontalSeparatorParameters().additive(false), _layoutData->structureHeight);

        processStructureTree();
        processStructureButtons();
    }
    ImGui::EndChild();
}

_GenomeEditorWidget::_GenomeEditorWidget(GenomeTabEditData const& editData, GenomeTabLayoutData const& layoutData)
    : _editData(editData)
    , _layoutData(layoutData)
{
    for (auto const& gene : editData->genome._genes) {
        try {
            auto name = gene._name;
            std::string const prefix = "Gene ";
            if (name.starts_with(prefix)) {
                std::string numberPart = name.substr(prefix.size());
                int number = std::stoi(numberPart);
                _sequenceNumberForCreatedGenes = std::max(_sequenceNumberForCreatedGenes, number + 1);
            }
        } catch (...) {
        }
    }
}

float _GenomeEditorWidget::processHeaderData()
{
    auto startPosY = ImGui::GetCursorPosY();
    AlienGui::Group(AlienGui::GroupParameters().text(tr("genome.properties")).highlighted(true));

    auto groupHeight = ImGui::GetCursorPosY() - startPosY;
    auto contentHeight = 0.0f;
    ImGui::SetNextWindowContentSize({ImGui::GetContentRegionAvail().x < scale(400.0f) ? scale(400.0f) : 0.0f, 0});
    if (ImGui::BeginChild("GenomeHeader", ImVec2(0, -_layoutData->structureHeight), 0, ImGuiWindowFlags_HorizontalScrollbar)) {

        auto rightColumnWidth = std::max(HeaderMinRightColumnWidth, scaleInverse(ImGui::GetContentRegionAvail().x - scale(HeaderMaxLeftColumnWidth)));

        AlienGui::InputText(
            AlienGui::InputTextParameters()
                .name("Genome name")
                .label(tr("genome.field.name"))
                .textWidth(rightColumnWidth)
                .tooltip(GenomeEditorPresentation::attributeDescription(EntityAttribute::GenomeName))
                .generateValueTooltip(tr("new.generate"))
                .generateValueFunc([] { return NameGeneratorService::get().createGenomeName(); }),
            _editData->genome._name);

        AlienGui::SliderFloat(
            AlienGui::SliderFloatParameters()
                .name("Front angle")
                .label(tr("genome.field.frontangle"))
                .format("%.1f")
                .min(-180.0f)
                .max(180.0f)
                .textWidth(rightColumnWidth)
                .tooltip(GenomeEditorPresentation::attributeDescription(EntityAttribute::GenomeFrontAngle)),
            &_editData->genome._frontAngle);

        AlienGui::Checkbox(
            AlienGui::CheckboxParameters()
                .name("Resistance to injection")
                .label(tr("genome.field.resistance"))
                .textWidth(rightColumnWidth)
                .tooltip(GenomeEditorPresentation::attributeDescription(EntityAttribute::GenomeResistanceToInjection)),
            &_editData->genome._resistanceToInjection);

        AlienGui::Checkbox(
            AlienGui::CheckboxParameters()
                .name("Apply meta-mutations")
                .label(tr("genome.field.metamutations"))
                .textWidth(rightColumnWidth)
                .tooltip(GenomeEditorPresentation::attributeDescription(EntityAttribute::GenomeApplyMetaMutations)),
            &_editData->genome._applyMetaMutations);

        _mutationRatesWidget.processAsSingleRow(_editData->genome._mutationRates, rightColumnWidth);
        contentHeight = ImGui::GetCursorPosY();
    }
    ImGui::EndChild();
    return groupHeight + contentHeight;
}

void _GenomeEditorWidget::processStructureTree()
{
    AlienGui::Group(AlienGui::GroupParameters().text(tr("genome.structure")).highlighted(true));

    if (ImGui::BeginChild("Structure", ImVec2(0, -ImGui::GetFrameHeightWithSpacing()))) {
        auto scrollToSelection = _selectedGeneFromPreviousFrame != _editData->selectedGeneIndex && !_selectionChangedFromTree;
        _selectedGeneFromPreviousFrame = _editData->selectedGeneIndex;
        _selectionChangedFromTree = false;

        auto const& customizationColors = _SimulationFacade::get()->getSimulationParameters().customizationColors.value;

        static ImGuiTableFlags flags = ImGuiTableFlags_Resizable | ImGuiTableFlags_Reorderable | ImGuiTableFlags_Hideable | ImGuiTableFlags_RowBg
            | ImGuiTableFlags_BordersInnerV | ImGuiTableFlags_ScrollY | ImGuiTableFlags_ScrollX;

        auto isWideEnough = ImGui::GetContentRegionAvail().x >= scale(StructureTableMinWidth);
        auto innerWidth = isWideEnough ? StretchColumnsToVisibleWidth : scale(StructureTableMinWidth);
        if (ImGui::BeginTable("Structure list", 4, flags, ImVec2(-1, -1), innerWidth)) {
            ImGui::TableSetupColumn((tr("genome.column.name") + "###Name").c_str(), ImGuiTableColumnFlags_NoHide | ImGuiTableColumnFlags_WidthStretch, 150.0f);
            ImGui::TableSetupColumn((tr("genome.column.type") + "###Type").c_str(), ImGuiTableColumnFlags_WidthStretch, 130.0f);
            ImGui::TableSetupColumn((tr("genome.column.references") + "###References").c_str(), ImGuiTableColumnFlags_WidthStretch, 75.0f);
            ImGui::TableSetupColumn((tr("genome.column.referencedby") + "###Referenced by").c_str(), ImGuiTableColumnFlags_WidthStretch, 90.0f);
            ImGui::TableSetupScrollFreeze(0, 1);
            ImGui::TableHeadersRow();

            for (auto const& [index, gene] : _editData->genome._genes | boost::adaptors::indexed(0)) {
                auto geneIndex = toInt(index);
                processGeneNode(geneIndex, gene, GenomeIssue::filterByGene(_editData->genomeIssues, geneIndex), scrollToSelection, customizationColors);
            }
            ImGui::EndTable();
        }
    }
    ImGui::EndChild();
}

namespace
{
    std::vector<GenomeIssue> filterIssues(std::vector<GenomeIssue> const& issues, std::function<bool(GenomeIssue const&)> const& predicate)
    {
        auto result = issues | std::views::filter(predicate);
        return std::vector(result.begin(), result.end());
    }

    int countWithoutFollowUps(std::vector<GenomeIssue> const& issues)
    {
        return toInt(std::ranges::count_if(issues, [](auto const& issue) { return !issue.isFollowUp(); }));
    }
}

void _GenomeEditorWidget::processGeneNode(
    int geneIndex,
    GeneDesc const& gene,
    std::vector<GenomeIssue> const& geneIssues,
    bool scrollToSelection,
    ColorVector<FloatColorRGB> const& customizationColors)
{
    ImGui::PushID(geneIndex);
    ImGui::TableNextRow();

    auto isSelectedGene = _editData->selectedGeneIndex == geneIndex;
    auto flags = ImGuiTreeNodeFlags_OpenOnArrow | ImGuiTreeNodeFlags_DefaultOpen;
    if (isSelectedGene && _editData->selectionLevel == GenomeSelectionLevel::Gene) {
        flags |= ImGuiTreeNodeFlags_Selected;
    }
    if (scrollToSelection && isSelectedGene) {
        ImGui::SetNextItemOpen(true);
    }

    // Column 0: identity, followed by the optional name in decent parentheses
    ImGui::TableNextColumn();
    auto geneLevelIssues = filterIssues(geneIssues, [](auto const& issue) { return !issue.nodeIndex.has_value() || issue.removesGene; });
    auto mostRelevantGeneLevelIssue = GenomeIssueDescription::findMostRelevantIssue(geneLevelIssues);
    auto isRemoved = std::ranges::any_of(geneIssues, &GenomeIssue::removesGene);
    if (mostRelevantGeneLevelIssue.has_value()) {
        ImGui::PushStyleColor(
            ImGuiCol_Text, isRemoved ? Const::WarningColor.Value : GenomeIssueDescription::getColor(mostRelevantGeneLevelIssue.value()).Value);
    }
    auto isOpen = AlienGui::TableRowTreeNode("##gene", GenomeEditorPresentation::format("genome.tree.gene", {{"index", std::to_string(geneIndex)}}), flags);
    if (mostRelevantGeneLevelIssue.has_value()) {
        ImGui::PopStyleColor();
    }
    if (ImGui::IsItemClicked() && !ImGui::IsItemToggledOpen()) {
        _editData->selectGene(geneIndex);
        _selectionChangedFromTree = true;
    }
    if (mostRelevantGeneLevelIssue.has_value()) {
        AlienGui::Tooltip(AlienGui::TooltipParameters().textFunc([&] { return GenomeIssueDescription::getTooltip(geneLevelIssues, _editData->genome); }));
    }
    if (!gene._name.empty()) {
        ImGui::SameLine();
        AlienGui::Text(AlienGui::TextParameters().text("(" + gene._name + ")").style(AlienGui::TextStyle::Decent));
    }
    auto numNodeLevelWarnings = countWithoutFollowUps(filterIssues(geneIssues, [](auto const& issue) { return issue.nodeIndex.has_value(); }));
    if (!isOpen && numNodeLevelWarnings > 0) {
        ImGui::SameLine();
        ImGui::PushStyleColor(ImGuiCol_Text, Const::WarningColor.Value);
        AlienGui::Text(ICON_FA_EXCLAMATION_TRIANGLE " " + std::to_string(numNodeLevelWarnings));
        ImGui::PopStyleColor();
    }
    if (scrollToSelection && isSelectedGene) {
        ImGui::SetScrollHereY();
    }

    // Column 1: the customization colors in use, followed by node count and shape
    ImGui::TableNextColumn();
    std::set<int> usedColors;
    for (auto const& node : gene._nodes) {
        usedColors.insert(node._color);
    }
    for (auto const& usedColor : usedColors) {
        float h, s, v;
        AlienGui::ConvertRGBtoHSV(customizationColors.values[usedColor].toRgbColor(), h, s, v);
        AlienGui::Chip(AlienGui::ChipParameters().dotColor(ImColor::HSV(h, s, v)).dotSize(ColorChipSize).spacing(ColorChipSpacing));
    }
    AlienGui::Text(std::to_string(gene._nodes.size()) + "-" + GenomeEditorPresentation::shapes().at(gene._shape));

    // Column 2: referenced genes
    ImGui::TableNextColumn();
    AlienGui::Text(StringHelper::join(GenomeDescAccessService::get().getReferences(gene)));

    // Column 3: referencing genes
    ImGui::TableNextColumn();
    AlienGui::Text(StringHelper::join(GenomeDescAccessService::get().getReferencedBy(_editData->genome, geneIndex)));

    if (isOpen) {
        for (auto const& [index, node] : gene._nodes | boost::adaptors::indexed(0)) {
            processNodeLeaf(geneIndex, toInt(index), gene, node, geneIssues, customizationColors);
        }
        ImGui::TreePop();
    }
    ImGui::PopID();
}

void _GenomeEditorWidget::processNodeLeaf(
    int geneIndex,
    int nodeIndex,
    GeneDesc const& gene,
    NodeDesc const& node,
    std::vector<GenomeIssue> const& geneIssues,
    ColorVector<FloatColorRGB> const& customizationColors)
{
    ImGui::PushID(nodeIndex);
    ImGui::TableNextRow();

    auto flags = ImGuiTreeNodeFlags_Leaf | ImGuiTreeNodeFlags_NoTreePushOnOpen;
    if (_editData->selectionLevel == GenomeSelectionLevel::Node && _editData->selectedGeneIndex == geneIndex
        && _editData->getSelectedNodeIndex() == nodeIndex) {
        flags |= ImGuiTreeNodeFlags_Selected;
    }

    // Column 0: identity
    ImGui::TableNextColumn();
    auto nodeIssues = filterIssues(geneIssues, [&](auto const& issue) { return issue.nodeIndex == nodeIndex; });
    auto mostRelevantIssue = GenomeIssueDescription::findMostRelevantIssue(nodeIssues);
    if (mostRelevantIssue.has_value()) {
        ImGui::PushStyleColor(ImGuiCol_Text, GenomeIssueDescription::getColor(mostRelevantIssue.value()).Value);
    }
    AlienGui::TableRowTreeNode("##node", GenomeEditorPresentation::format("genome.tree.node", {{"index", std::to_string(nodeIndex)}}), flags);
    if (mostRelevantIssue.has_value()) {
        ImGui::PopStyleColor();
    }
    if (ImGui::IsItemClicked()) {
        _editData->selectNode(geneIndex, nodeIndex);
        _selectionChangedFromTree = true;
    }
    if (mostRelevantIssue.has_value()) {
        AlienGui::Tooltip(AlienGui::TooltipParameters().textFunc([&] { return GenomeIssueDescription::getTooltip(nodeIssues, _editData->genome); }));
    }

    // Column 1: cell type. With homogeneous cell type every node shows the cell type of the first node
    ImGui::TableNextColumn();
    float h, s, v;
    AlienGui::ConvertRGBtoHSV(customizationColors.values[node._color].toRgbColor(), h, s, v);
    AlienGui::Chip(AlienGui::ChipParameters().dotColor(ImColor::HSV(h, s, v)).dotSize(ColorChipSize).spacing(ColorChipSpacing));
    auto nodeType = gene.getCellType(nodeIndex);
    AlienGui::Text(GenomeEditorPresentation::cellTypes().at(nodeType));
    auto isCutOff = std::ranges::any_of(
        geneIssues, [&](auto const& issue) { return std::ranges::find(issue.cutOffNodeIndices, nodeIndex) != issue.cutOffNodeIndices.end(); });
    if (isCutOff && nodeType != CellType_Void) {
        ImGui::SameLine();
        ImGui::PushStyleColor(ImGuiCol_Text, Const::WarningColor.Value);
        AlienGui::Text(std::string(ICON_FA_LONG_ARROW_ALT_RIGHT) + " " + GenomeEditorPresentation::cellTypes().at(CellType_Void));
        ImGui::PopStyleColor();
    }

    // Column 2: the gene this node constructs
    ImGui::TableNextColumn();
    if (node._constructor.has_value()) {
        auto constructedGeneIndex = node._constructor->_geneIndex;
        auto text = GenomeEditorPresentation::format("genome.tree.gene", {{"index", std::to_string(constructedGeneIndex)}});
        auto const& genes = _editData->genome._genes;
        if (_editData->hasValidGeneIndex(constructedGeneIndex) && !genes.at(constructedGeneIndex)._name.empty()) {
            text += ": " + genes.at(constructedGeneIndex)._name;
        }
        AlienGui::Text(text);
    }

    // Column 3: referencing genes -- only genes have them
    ImGui::TableNextColumn();

    ImGui::PopID();
}

void _GenomeEditorWidget::processStructureButtons()
{
    if (AlienGui::ActionButton(AlienGui::ActionButtonParameters().buttonText(ICON_FA_PLUS_CIRCLE).tooltip(tr("genome.gene.add")))) {
        onAddGene();
    }

    ImGui::SameLine();
    ImGui::BeginDisabled(!_editData->selectedGeneIndex.has_value());
    if (AlienGui::ActionButton(AlienGui::ActionButtonParameters().buttonText(ICON_FA_PLUS_SQUARE).tooltip(tr("genome.node.add")))) {
        onAddNode();
    }
    ImGui::EndDisabled();

    ImGui::SameLine();
    AlienGui::VerticalSeparator(20.0f);

    ImGui::SameLine();
    auto nodeLevel = _editData->isNodeLevelSelected();
    ImGui::BeginDisabled(!_editData->selectedGeneIndex.has_value());
    if (AlienGui::ActionButton(
            AlienGui::ActionButtonParameters().buttonText(ICON_FA_MINUS_CIRCLE).tooltip(nodeLevel ? tr("genome.node.remove") : tr("genome.gene.remove")))) {
        if (nodeLevel) {
            onRemoveNode();
        } else {
            onRemoveGene();
        }
    }
    ImGui::EndDisabled();

    ImGui::SameLine();
    nodeLevel = _editData->isNodeLevelSelected();
    auto canMoveUpward = nodeLevel ? _editData->getSelectedNodeIndex().value() > 0 : _editData->selectedGeneIndex.value_or(0) > 0;
    ImGui::BeginDisabled(!canMoveUpward);
    if (AlienGui::ActionButton(
            AlienGui::ActionButtonParameters().buttonText(ICON_FA_CHEVRON_CIRCLE_UP).tooltip(nodeLevel ? tr("genome.node.up") : tr("genome.gene.up")))) {
        if (nodeLevel) {
            onMoveNodeUpward();
        } else {
            onMoveGeneUpward();
        }
    }
    ImGui::EndDisabled();

    ImGui::SameLine();
    nodeLevel = _editData->isNodeLevelSelected();
    auto canMoveDownward = false;
    if (nodeLevel) {
        canMoveDownward = _editData->getSelectedNodeIndex().value() + 1 < toInt(_editData->getSelectedGeneRef()._nodes.size());
    } else if (_editData->selectedGeneIndex.has_value()) {
        canMoveDownward = _editData->selectedGeneIndex.value() + 1 < toInt(_editData->genome._genes.size());
    }
    ImGui::BeginDisabled(!canMoveDownward);
    if (AlienGui::ActionButton(
            AlienGui::ActionButtonParameters().buttonText(ICON_FA_CHEVRON_CIRCLE_DOWN).tooltip(nodeLevel ? tr("genome.node.down") : tr("genome.gene.down")))) {
        if (nodeLevel) {
            onMoveNodeDownward();
        } else {
            onMoveGeneDownward();
        }
    }
    ImGui::EndDisabled();

    ImGui::SameLine();
    AlienGui::VerticalSeparator(20.0f);

    ImGui::SameLine();
    ImGui::BeginDisabled(_editData->genomeIssues.empty());
    if (AlienGui::ActionButton(AlienGui::ActionButtonParameters().buttonText(ICON_FA_MAGIC).tooltip(tr("genome.fix.help")))) {
        onFixAllIssues();
    }
    ImGui::EndDisabled();
}

void _GenomeEditorWidget::onAddGene()
{
    auto& genome = _editData->genome;
    auto name = "Gene " + std::to_string(_sequenceNumberForCreatedGenes++);
    if (genome._genes.empty()) {
        auto newGene = GeneDesc().name(name).nodes({NodeDesc()}).shape(ConstructorShape_Segment);
        GenomeDescEditService::get().addGene(genome, 0, newGene);
        _editData->selectGene(0);
    } else {
        int insertIndex;
        if (_editData->selectedGeneIndex.has_value()) {
            insertIndex = _editData->selectedGeneIndex.value();
        } else {
            insertIndex = toInt(genome._genes.size()) - 1;
        }

        auto newGene = GeneDesc().name(name).nodes({NodeDesc()}).shape(ConstructorShape_Segment);
        GenomeDescEditService::get().addGene(genome, insertIndex, newGene);

        // Adapt gene selection
        _editData->selectGene(insertIndex + 1);

        // Adapt node selection
        std::map<int, int> newSelectedNodeByGeneIndex;
        for (auto const& [index, selectedNode] : _editData->selectedNodeByGeneIndex) {
            if (index <= insertIndex) {
                newSelectedNodeByGeneIndex.emplace(index, selectedNode);
            } else {
                newSelectedNodeByGeneIndex.emplace(index + 1, selectedNode);
            }
        }
        _editData->selectedNodeByGeneIndex = newSelectedNodeByGeneIndex;
        _editData->setSelectedNodeIndex(0);
    }
}

void _GenomeEditorWidget::onAddNode()
{
    auto& gene = _editData->getSelectedGeneRef();
    auto selectedNode = _editData->getSelectedNodeIndex();
    auto geneIndex = _editData->selectedGeneIndex.value();
    if (gene._nodes.empty()) {
        GenomeDescEditService::get().addNode(gene, 0, NodeDesc());
        _editData->selectNode(geneIndex, 0);
    } else {
        int insertIndex = selectedNode.has_value() ? selectedNode.value() : toInt(gene._nodes.size()) - 1;
        auto insertAtBack = insertIndex == toInt(gene._nodes.size()) - 1;

        auto& nodeAtInsertIndex = gene._nodes.at(insertIndex);
        int color = nodeAtInsertIndex._color;

        auto newNode = NodeDesc().color(color);
        if (insertAtBack) {
            nodeAtInsertIndex._neuralNetwork._connectionWeights.at(0) = 1;
            newNode._neuralNetwork._connectionWeights.at(0) = 0;
        }
        GenomeDescEditService::get().addNode(gene, insertIndex, newNode);

        _editData->selectNode(geneIndex, insertIndex + 1);
    }
}

void _GenomeEditorWidget::onRemoveNode()
{
    int removeIndex = _editData->getSelectedNodeIndex().value();
    auto& gene = _editData->getSelectedGeneRef();

    GenomeDescEditService::get().removeNode(gene, removeIndex);

    // Adapt node selection
    auto& nodes = gene._nodes;
    if (nodes.empty()) {
        _editData->setSelectedNodeIndex(std::nullopt);
        _editData->selectionLevel = GenomeSelectionLevel::Gene;
    } else if (removeIndex >= toInt(nodes.size())) {
        _editData->setSelectedNodeIndex(toInt(nodes.size()) - 1);
    } else {
        _editData->setSelectedNodeIndex(removeIndex);
    }
}

void _GenomeEditorWidget::onMoveNodeUpward()
{
    auto indexToMove = _editData->getSelectedNodeIndex().value();
    auto& gene = _editData->getSelectedGeneRef();

    if (indexToMove == 1 && gene._nodes.at(indexToMove).getCellType() == CellType_Void) {
        GenericMessageDialog::get().localizedInformation("Error", "common.error", "genome.error.firstvoid");
        return;
    }

    GenomeDescEditService::get().swapNodes(gene, indexToMove - 1);
    _editData->setSelectedNodeIndex(indexToMove - 1);
}

void _GenomeEditorWidget::onMoveNodeDownward()
{
    auto indexToMove = _editData->getSelectedNodeIndex().value();
    auto& gene = _editData->getSelectedGeneRef();

    if (indexToMove == gene._nodes.size() - 2 && gene._nodes.at(indexToMove).getCellType() == CellType_Void) {
        GenericMessageDialog::get().localizedInformation("Error", "common.error", "genome.error.lastvoid");
        return;
    }

    GenomeDescEditService::get().swapNodes(gene, indexToMove);
    _editData->setSelectedNodeIndex(indexToMove + 1);
}

void _GenomeEditorWidget::onRemoveGene()
{
    auto referencedBy = GenomeDescAccessService::get().getReferencedBy(_editData->genome, _editData->selectedGeneIndex.value());
    if (!referencedBy.empty()) {
        GenericMessageDialog::get().localizedInformation(
            "Error",
            "common.error",
            referencedBy.size() == 1 ? "genome.error.used.one" : "genome.error.used.many",
            {{"genes", StringHelper::join(referencedBy)}});
        return;
    }
    if (_editData->selectedGeneIndex.value() == 0) {
        GenericMessageDialog::get().localizedYesNo("Delete root gene", "genome.delete.title", "genome.delete.confirm", [this] { this->removeGeneIntern(); });
        return;
    }
    removeGeneIntern();
}

void _GenomeEditorWidget::onMoveGeneUpward()
{
    if (_editData->selectedGeneIndex.value() == 1) {
        GenericMessageDialog::get().localizedYesNo("Swap root gene", "genome.swap.title", "genome.swap.confirm", [this] { this->moveGeneUpwardIntern(); });
        return;
    }
    moveGeneUpwardIntern();
}

void _GenomeEditorWidget::onMoveGeneDownward()
{
    if (_editData->selectedGeneIndex.value() == 0) {
        GenericMessageDialog::get().localizedYesNo("Swap root gene", "genome.swap.title", "genome.swap.confirm", [this] { this->moveGeneDownwardIntern(); });
        return;
    }
    moveGeneDownwardIntern();
}

void _GenomeEditorWidget::onFixAllIssues()
{
    GenericMessageDialog::get().localizedYesNo("Fix all warnings", "genome.fix.title", "genome.fix.confirm", [this] { this->fixAllIssuesIntern(); });
}

void _GenomeEditorWidget::removeGeneIntern()
{
    int removeIndex = _editData->selectedGeneIndex.value();

    GenomeDescEditService::get().removeGene(_editData->genome, removeIndex);

    // Adapt gene selection
    auto& genes = _editData->genome._genes;
    if (genes.empty()) {
        _editData->selectedGeneIndex.reset();
        _editData->selectionLevel = GenomeSelectionLevel::Gene;
    } else if (removeIndex >= toInt(genes.size())) {
        _editData->selectGene(toInt(genes.size()) - 1);
    } else {
        _editData->selectGene(removeIndex);
    }

    // Adapt node selection
    std::map<int, int> newSelectedNodeByGeneIndex;
    for (auto const& [index, selectedNode] : _editData->selectedNodeByGeneIndex) {
        if (index < removeIndex) {
            newSelectedNodeByGeneIndex.emplace(index, selectedNode);
        } else if (index > removeIndex) {
            newSelectedNodeByGeneIndex.emplace(index - 1, selectedNode);
        }
    }
    _editData->selectedNodeByGeneIndex = newSelectedNodeByGeneIndex;
}

void _GenomeEditorWidget::moveGeneUpwardIntern()
{
    int indexToMove = _editData->selectedGeneIndex.value();
    GenomeDescEditService::get().swapGenes(_editData->genome, indexToMove - 1);

    // Adapt gene selection
    --_editData->selectedGeneIndex.value();

    // Adapt node selection
    std::map<int, int> newSelectedNodeByGeneIndex;
    for (auto const& [index, selectedNode] : _editData->selectedNodeByGeneIndex) {
        if (index == indexToMove) {
            newSelectedNodeByGeneIndex.emplace(index - 1, selectedNode);
        } else if (index == indexToMove - 1) {
            newSelectedNodeByGeneIndex.emplace(index + 1, selectedNode);
        } else {
            newSelectedNodeByGeneIndex.emplace(index, selectedNode);
        }
    }
    _editData->selectedNodeByGeneIndex = newSelectedNodeByGeneIndex;
}

void _GenomeEditorWidget::moveGeneDownwardIntern()
{
    int indexToMove = _editData->selectedGeneIndex.value();
    GenomeDescEditService::get().swapGenes(_editData->genome, indexToMove);

    // Adapt gene selection
    ++_editData->selectedGeneIndex.value();

    // Adapt node selection
    std::map<int, int> newSelectedNodeByGeneIndex;
    for (auto const& [index, selectedNode] : _editData->selectedNodeByGeneIndex) {
        if (index == indexToMove) {
            newSelectedNodeByGeneIndex.emplace(index + 1, selectedNode);
        } else if (index == indexToMove + 1) {
            newSelectedNodeByGeneIndex.emplace(index - 1, selectedNode);
        } else {
            newSelectedNodeByGeneIndex.emplace(index, selectedNode);
        }
    }
    _editData->selectedNodeByGeneIndex = newSelectedNodeByGeneIndex;
}

void _GenomeEditorWidget::fixAllIssuesIntern()
{
    auto newGeneIndexByOldGeneIndex = DescValidationService::get().fixGenomeIssues(_editData->genome);

    if (_editData->selectedGeneIndex.has_value()) {
        auto newGeneIndex = newGeneIndexByOldGeneIndex.find(_editData->selectedGeneIndex.value());
        if (newGeneIndex != newGeneIndexByOldGeneIndex.end()) {
            _editData->selectedGeneIndex = newGeneIndex->second;
        } else {
            _editData->selectGene(0);
        }
    }

    std::map<int, int> newSelectedNodeByGeneIndex;
    for (auto const& [oldGeneIndex, selectedNode] : _editData->selectedNodeByGeneIndex) {
        if (auto newGeneIndex = newGeneIndexByOldGeneIndex.find(oldGeneIndex); newGeneIndex != newGeneIndexByOldGeneIndex.end()) {
            newSelectedNodeByGeneIndex.emplace(newGeneIndex->second, selectedNode);
        }
    }
    _editData->selectedNodeByGeneIndex = newSelectedNodeByGeneIndex;
}

